    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;CteSqlSelect&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;    SELECT \n      N.[Id], \n      N.[Actiune], \n      NomA.Denumire AS DenumireActiune, \n      N.[Aplicatie], \n      NomApS.Nume AS NumeAplicatie, \n      NomApS.URL, \n      NomU.Nume AS NumeInstitutie, \n      FORMAT(N.[Date], &#39;dd.MM.yyyy HH:mm&#39;) AS [Date], \n      N.[TipData], \n      NomTD.Denumire AS DenumireTipData,\n      N.IsInAppNotified\n    FROM \n      [app].[Notificare] N \n      INNER JOIN app.Nomenclatoractiuni NomA ON N.Actiune = NomA.Id \n      INNER JOIN app.NomenclatorAplicatiiSursa NomApS ON N.Aplicatie = NomApS.Id \n      INNER JOIN app.Nomenclatorutilizator NomU ON NomApS.Institutie = NomU.Id \n      INNER JOIN app.NomenclatorTipurideDate NomTD ON N.TipData = NomTD.Id\n      INNER JOIN app.Cetatean C ON N.Cetatean = C.Id\n    WHERE C.UserId = @idUser&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[User:UserId]&quot;,&quot;name&quot;:&quot;idUser&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;OrderBy&quot;:&quot;IsInAppNotified ASC&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;